insert into public.recipes (id,name_ar,name_en,meal_types,category,prep_minutes,cost_tier,kid_friendly,ingredients,steps_ar,steps_en,tags) values ('oats_berries','شوفان بالحليب والفراولة والشيا','Oats with milk, berries & chia',array['breakfast']::meal_type[],'breakfast',7,1,true,'[{"food_item_id":"oats","grams":50,"substitutes":[]},{"food_item_id":"milk_lowfat","grams":200,"substitutes":["yogurt","greek_yogurt"]},{"food_item_id":"strawberries","grams":80,"substitutes":["banana","apple"]},{"food_item_id":"chia","grams":10,"substitutes":["almonds","walnuts"]},{"food_item_id":"honey","grams":8,"substitutes":[]}]'::jsonb,array['اطهُ الشوفان مع الحليب على نار هادئة 4 دقائق.','أضف الشيا وقلّب.','زيّن بالفراولة ورشة عسل.']::text[],array['Simmer oats in milk for 4 minutes.','Stir in chia seeds.','Top with strawberries and a drizzle of honey.']::text[],array['breakfast','vegetarian']::text[]) on conflict (id) do update set ingredients=excluded.ingredients, steps_ar=excluded.steps_ar, steps_en=excluded.steps_en;
insert into public.recipes (id,name_ar,name_en,meal_types,category,prep_minutes,cost_tier,kid_friendly,ingredients,steps_ar,steps_en,tags) values ('foul_plate','فول مدمس بزيت الزيتون مع خبز أسمر','Foul medames with olive oil & pita',array['breakfast','dinner']::meal_type[],'legumes',10,1,false,'[{"food_item_id":"fava","grams":180,"substitutes":["chickpeas","lentils"]},{"food_item_id":"olive_oil","grams":8,"substitutes":[]},{"food_item_id":"lemon","grams":10,"substitutes":[]},{"food_item_id":"tomato","grams":70,"substitutes":[]},{"food_item_id":"cucumber","grams":60,"substitutes":[]},{"food_item_id":"pita","grams":50,"substitutes":["ww_bread"]}]'::jsonb,array['سخّن الفول واهرسه قليلاً.','أضف الليمون وزيت الزيتون.','قدّمه مع الطماطم والخيار والخبز.']::text[],array['Warm the beans and lightly mash.','Add lemon juice and olive oil.','Serve with tomato, cucumber and pita.']::text[],array['legumes','vegetarian']::text[]) on conflict (id) do update set ingredients=excluded.ingredients, steps_ar=excluded.steps_ar, steps_en=excluded.steps_en;
insert into public.recipes (id,name_ar,name_en,meal_types,category,prep_minutes,cost_tier,kid_friendly,ingredients,steps_ar,steps_en,tags) values ('greek_yogurt_bowl','زبادي يوناني باللوز والفراولة','Greek yogurt bowl with almonds & berries',array['breakfast','snack']::meal_type[],'breakfast',3,2,true,'[{"food_item_id":"greek_yogurt","grams":200,"substitutes":["cottage","yogurt"]},{"food_item_id":"strawberries","grams":80,"substitutes":["banana","apple","orange"]},{"food_item_id":"almonds","grams":15,"substitutes":["walnuts","chia"]},{"food_item_id":"honey","grams":8,"substitutes":[]}]'::jsonb,array['ضع الزبادي في وعاء.','أضف الفاكهة واللوز والعسل.']::text[],array['Spoon yogurt into a bowl.','Top with fruit, almonds and honey.']::text[],array['breakfast','vegetarian']::text[]) on conflict (id) do update set ingredients=excluded.ingredients, steps_ar=excluded.steps_ar, steps_en=excluded.steps_en;
insert into public.recipes (id,name_ar,name_en,meal_types,category,prep_minutes,cost_tier,kid_friendly,ingredients,steps_ar,steps_en,tags) values ('veggie_omelette','أومليت بالسبانخ والفيتا مع خبز','Spinach & feta omelette with toast',array['breakfast','dinner']::meal_type[],'plate',10,1,true,'[{"food_item_id":"egg","grams":120,"substitutes":[]},{"food_item_id":"spinach","grams":40,"substitutes":["mushrooms","bell_pepper"]},{"food_item_id":"tomato","grams":60,"substitutes":[]},{"food_item_id":"feta","grams":20,"substitutes":["mozzarella","cottage"]},{"food_item_id":"olive_oil","grams":5,"substitutes":[]},{"food_item_id":"ww_bread","grams":40,"substitutes":["pita"]}]'::jsonb,array['اخفق البيض.','شوّح السبانخ في زيت الزيتون دقيقة.','أضف البيض والفيتا واطهُ حتى يتماسك.','قدّمه مع الطماطم والخبز.']::text[],array['Whisk the eggs.','Sauté spinach in olive oil for a minute.','Add eggs and feta; cook until set.','Serve with tomato and toast.']::text[],array['plate','vegetarian']::text[]) on conflict (id) do update set ingredients=excluded.ingredients, steps_ar=excluded.steps_ar, steps_en=excluded.steps_en;
insert into public.recipes (id,name_ar,name_en,meal_types,category,prep_minutes,cost_tier,kid_friendly,ingredients,steps_ar,steps_en,tags) values ('cottage_plate','جبن قريش مع خضار وخبز أسمر','Cottage cheese plate with veggies',array['breakfast','dinner']::meal_type[],'plate',5,1,true,'[{"food_item_id":"cottage","grams":150,"substitutes":["greek_yogurt","feta"]},{"food_item_id":"cucumber","grams":80,"substitutes":[]},{"food_item_id":"tomato","grams":80,"substitutes":[]},{"food_item_id":"olive_oil","grams":5,"substitutes":[]},{"food_item_id":"ww_bread","grams":50,"substitutes":["pita"]}]'::jsonb,array['قطّع الخضار.','رتّب الجبن والخضار مع رشة زيت زيتون.','قدّمه مع الخبز.']::text[],array['Slice the vegetables.','Plate cheese and veggies with a drizzle of olive oil.','Serve with bread.']::text[],array['plate','vegetarian']::text[]) on conflict (id) do update set ingredients=excluded.ingredients, steps_ar=excluded.steps_ar, steps_en=excluded.steps_en;
insert into public.recipes (id,name_ar,name_en,meal_types,category,prep_minutes,cost_tier,kid_friendly,ingredients,steps_ar,steps_en,tags) values ('pb_banana_toast','توست بزبدة الفول السوداني والموز','Peanut butter & banana toast',array['breakfast','snack']::meal_type[],'sandwich',3,1,true,'[{"food_item_id":"ww_bread","grams":60,"substitutes":[]},{"food_item_id":"peanut_butter","grams":20,"substitutes":["tahini","almonds"]},{"food_item_id":"banana","grams":80,"substitutes":["strawberries","apple"]}]'::jsonb,array['حمّص الخبز.','ادهنه بزبدة الفول السوداني.','أضف شرائح الموز.']::text[],array['Toast the bread.','Spread peanut butter.','Top with banana slices.']::text[],array['sandwich','vegetarian']::text[]) on conflict (id) do update set ingredients=excluded.ingredients, steps_ar=excluded.steps_ar, steps_en=excluded.steps_en;
insert into public.recipes (id,name_ar,name_en,meal_types,category,prep_minutes,cost_tier,kid_friendly,ingredients,steps_ar,steps_en,tags) values ('chicken_rice_bowl','وعاء دجاج مشوي مع أرز بني وبروكلي','Grilled chicken, brown rice & broccoli bowl',array['lunch','dinner']::meal_type[],'bowl',25,2,true,'[{"food_item_id":"chicken_breast","grams":150,"substitutes":["tuna","shrimp","lean_beef","salmon"]},{"food_item_id":"rice_brown","grams":150,"substitutes":["rice_white","quinoa","bulgur","sweet_potato","potato"]},{"food_item_id":"broccoli","grams":100,"substitutes":["spinach","carrot","bell_pepper"]},{"food_item_id":"olive_oil","grams":5,"substitutes":[]}]'::jsonb,array['تبّل الدجاج واشوِه 6–7 دقائق لكل جهة.','اطهُ البروكلي على البخار 5 دقائق.','قدّمه فوق الأرز مع رشة زيت زيتون.']::text[],array['Season and grill chicken 6–7 min per side.','Steam broccoli for 5 minutes.','Serve over rice with a drizzle of olive oil.']::text[],array['bowl']::text[]) on conflict (id) do update set ingredients=excluded.ingredients, steps_ar=excluded.steps_ar, steps_en=excluded.steps_en;
